+/* Forward declaration — mutually recursive with populate_protocol_field_trees. */
+// NOLINTNEXTLINE(misc-no-recursion)
+static void populate_protocol_wildcard_trees(dict_wildcardfield_def_t *wdef, GSList *proto_list,
